-- =====================================================================
-- 0151_terminos_editables.sql — los Términos y Condiciones, editables
--
-- «Términos y condiciones editables desde el panel administrativo.»
--
-- Hasta hoy el documento vivía escrito dentro de un componente de React
-- (`LegalTerms.tsx`, 414 líneas de JSX). Cambiar una coma de una cláusula
-- costaba un despliegue, y quien redacta el contrato no es quien despliega.
--
-- ── POR QUÉ SE GUARDA UNA ESTRUCTURA Y NO HTML ───────────────────────────────
--
-- Es la decisión que gobierna todo lo demás. Un editor de texto enriquecido que
-- guarde HTML es el camino corto y aquí es el equivocado: esta página la abre
-- CUALQUIERA sin sesión —incluido el revisor de Google Play, que la tiene
-- registrada como la política de privacidad de la ficha y la vuelve a mirar en
-- cada actualización—, y pintar HTML que salió de un formulario obliga a
-- sanearlo. Un solo hueco en ese saneado es un <script> almacenado en la página
-- legal de la empresa, servido a todo el que entre.
--
-- Así que el valor es un ARRAY DE BLOQUES:
--
--   [{"tipo": "titulo",  "texto": [{"t": "1. Objeto y alcance"}]},
--    {"tipo": "parrafo", "texto": [{"t": "LA EMPRESA pone a "},
--                                  {"t": "disposición", "b": true}]}]
--
-- El front recorre esa estructura y construye elementos de React. No usa
-- `dangerouslySetInnerHTML` en ningún punto, así que no hay forma de que quien
-- edita produzca una etiqueta. Es el mismo criterio de `textoConFormato` para
-- las descripciones de los avisos, y reutiliza sus fragmentos.
--
-- Los enlaces tampoco se guardan: el correo se escribe como texto y el front lo
-- reconoce al pintar. Un `href` guardado admitiría `javascript:`.
--
-- ── POR QUÉ UNA FUNCIÓN PROPIA Y NO `get_settings()` ─────────────────────────
--
-- `system_settings` tiene RLS y `get_settings()` solo responde al personal.
-- Esto lo lee TODO EL MUNDO, con sesión y sin ella.
--
-- Y por qué no una `get_public_setting(key)` genérica, que sería más cómoda: en
-- `system_settings` hay secretos —`payment_worker_secret`— y una función así los
-- dejaría al alcance de cualquiera con la clave anónima, que viaja dentro del
-- JavaScript de la web. Las claves van escritas a mano aquí dentro, igual que
-- en la 0134 y la 0141: para exponer algo hay que añadirlo a propósito.
--
-- ── LA FECHA NO SE TECLEA ────────────────────────────────────────────────────
--
-- `legal_actualizado` lo escribe el panel solo, al guardar. Una fecha de última
-- actualización que hay que acordarse de cambiar a mano acaba mintiendo, y en
-- un documento legal eso es justo lo que no puede pasar.
--
-- Idempotente.
-- =====================================================================

create or replace function public.documento_legal()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'bloques', (select value from public.system_settings where key = 'legal_documento'),
    -- `#>> '{}'` saca el texto plano del jsonb string. Sin esto llegaría
    -- entrecomillado y se pintarían las comillas al pie del documento.
    'actualizado', (select value #>> '{}' from public.system_settings
                     where key = 'legal_actualizado')
  );
$$;

-- Desde la 0104 una función nueva nace SIN execute para anon/authenticated. Sin
-- estas dos líneas la página legal sale vacía y sin decir por qué: un 42501 que
-- el `catch` del front se traga. Y esa página vacía es el rechazo de Play.
revoke execute on function public.documento_legal() from public;
grant  execute on function public.documento_legal() to anon, authenticated;

comment on function public.documento_legal() is
  'Términos y Condiciones + Política de Privacidad, legibles sin sesión. '
  'Devuelve {bloques, actualizado}. Expone solo las dos claves legal_* escritas '
  'a mano en su cuerpo — no generalizar a get_public_setting(key), que dejaría '
  'al alcance de la clave anónima cualquier secreto de system_settings.';

-- El punto de partida: el documento tal y como estaba escrito en el código.
--
-- `do nothing`, como en la 0141: si ya hay un texto editado, un despliegue no
-- lo pisa. Perder una redacción del abogado por reaplicar una migración sería
-- de las cosas más caras de deshacer.
--
-- Lo de abajo NO se escribe a mano: sale de `src/lib/legalPorDefecto.ts` a
-- través de `scripts/generar-semilla-legal.mjs`, y una prueba comprueba que las
-- dos copias siguen diciendo lo mismo.

-- <<< SEMILLA GENERADA: no editar a mano (scripts/generar-semilla-legal.mjs)
-- 68 bloques. Para cambiar el texto se edita
-- src/lib/legalPorDefecto.ts y se vuelve a ejecutar el generador.
insert into public.system_settings (key, value, label) values
  ('legal_documento', '[{"tipo":"epigrafe","texto":[{"t":"Publicación de Avisos Clasificados"}]},{"tipo":"parrafo","texto":[{"t":"El presente documento (en adelante, los \"Términos y Condiciones\") regula el acceso y uso del servicio de publicación de avisos clasificados, con y sin opción de visibilidad destacada (en adelante, el \"Servicio\"), ofrecido por CORP LOZANOCHEFFER SAC, identificada con RUC N° 20616009061, con domicilio fiscal en Ramal Sun S/N – Huaca del Sol - Moche, Trujillo, Perú (en adelante, \"LA EMPRESA\"). Al registrarse, contratar, acceder o utilizar el Servicio, el usuario (en adelante, \"EL CLIENTE\") declara haber leído, comprendido y aceptado de forma libre, expresa, informada e inequívoca el contenido íntegro de estos Términos y Condiciones, incluyendo la Política de Tratamiento de Datos Personales aquí contenida."}]},{"tipo":"titulo","texto":[{"t":"1. Objeto y alcance del servicio"}]},{"tipo":"parrafo","texto":[{"t":"LA EMPRESA pone a disposición de EL CLIENTE una plataforma digital para la publicación de avisos clasificados, los cuales podrán contratarse bajo dos modalidades:"}]},{"tipo":"vinheta","texto":[{"t":"Aviso sin visibilidad destacada:","b":true},{"t":" publicación estándar del aviso dentro del listado general de la categoría correspondiente, sujeta a los tiempos y posiciones determinados por el algoritmo de ordenamiento de la plataforma."}]},{"tipo":"vinheta","texto":[{"t":"Aviso con visibilidad destacada:","b":true},{"t":" publicación que incluye beneficios adicionales de posicionamiento, tales como mayor exposición, ubicación preferente, renovación automática de vigencia u otros atributos descritos en el plan contratado, conforme a las tarifas vigentes publicadas por LA EMPRESA."}]},{"tipo":"parrafo","texto":[{"t":"La aceptación de estos Términos y Condiciones es condición previa, necesaria e indispensable para acceder a cualquiera de las modalidades del Servicio."}]},{"tipo":"titulo","texto":[{"t":"2. Aceptación del contrato"}]},{"tipo":"vinheta","texto":[{"t":"La ejecución de cualquier acción de contratación, registro, pago o publicación de un aviso constituye la manifestación expresa de la voluntad de EL CLIENTE de aceptar íntegramente estos Términos y Condiciones, con el mismo valor y efectos jurídicos que una firma manuscrita, conforme a lo establecido en el artículo 141 y 141-A del Código Civil peruano y en la Ley N° 27269, Ley de Firmas y Certificados Digitales."}]},{"tipo":"vinheta","texto":[{"t":"LA EMPRESA podrá modificar el contenido de estos Términos y Condiciones en cualquier momento, notificando los cambios a través de la plataforma o al correo electrónico registrado por EL CLIENTE. El uso continuado del Servicio luego de dicha notificación implica la aceptación de las modificaciones."}]},{"tipo":"vinheta","texto":[{"t":"Si EL CLIENTE no está de acuerdo con los presentes Términos y Condiciones, deberá abstenerse de utilizar el Servicio."}]},{"tipo":"titulo","texto":[{"t":"3. Marco normativo aplicable"}]},{"tipo":"parrafo","texto":[{"t":"El tratamiento de los datos personales de EL CLIENTE por parte de LA EMPRESA se rige por el siguiente marco normativo:"}]},{"tipo":"vinheta","texto":[{"t":"Normativa nacional (Perú):","b":true},{"t":" Ley N° 29733, Ley de Protección de Datos Personales, y su Reglamento aprobado por Decreto Supremo N° 003-2013-JUS, así como las directivas emitidas por la Autoridad Nacional de Protección de Datos Personales (ANPD); Constitución Política del Perú, artículo 2, inciso 6; Código Civil; Código de Protección y Defensa del Consumidor (Ley N° 29571); y Ley N° 27269, Ley de Firmas y Certificados Digitales."}]},{"tipo":"vinheta","texto":[{"t":"Estándares y principios internacionales:","b":true},{"t":" se han considerado, de manera referencial y complementaria, principios reconocidos en el Reglamento General de Protección de Datos de la Unión Europea (RGPD - UE 2016/679), las Directrices de la OCDE sobre Privacidad, y los principios universales de protección de datos (legalidad, finalidad, proporcionalidad, calidad, seguridad, disposición de recurso, nivel de protección adecuado y consentimiento), en lo que resulte aplicable y no contravenga la normativa peruana."}]},{"tipo":"titulo","texto":[{"t":"4. Datos personales recopilados"}],"ancla":"datos-personales"},{"tipo":"parrafo","texto":[{"t":"Para la prestación del Servicio, LA EMPRESA podrá recopilar y tratar las siguientes categorías de datos personales de EL CLIENTE:"}]},{"tipo":"vinheta","texto":[{"t":"Datos de identificación:","b":true},{"t":" nombres y apellidos, tipo y número de documento de identidad (DNI, RUC, carné de extranjería o pasaporte), fecha de nacimiento."}]},{"tipo":"vinheta","texto":[{"t":"Datos de contacto:","b":true},{"t":" correo electrónico, número telefónico, dirección física, ciudad y país de residencia."}]},{"tipo":"vinheta","texto":[{"t":"Datos de facturación y pago:","b":true},{"t":" información requerida para la emisión de comprobantes de pago y el procesamiento de transacciones, gestionados a través de pasarelas de pago certificadas."}]},{"tipo":"vinheta","texto":[{"t":"Datos de navegación y uso:","b":true},{"t":" dirección IP, identificadores de dispositivo, cookies, historial de avisos publicados, preferencias de búsqueda y estadísticas de interacción con la plataforma."}]},{"tipo":"vinheta","texto":[{"t":"Datos contenidos en los avisos:","b":true},{"t":" la información que EL CLIENTE decida incluir voluntariamente en el contenido del aviso publicado, siendo de su exclusiva responsabilidad evitar la inclusión de datos sensibles o de terceros sin autorización."}]},{"tipo":"titulo","texto":[{"t":"5. Finalidad del tratamiento"}]},{"tipo":"parrafo","texto":[{"t":"Los datos personales de EL CLIENTE serán tratados para las siguientes finalidades:"}]},{"tipo":"vinheta","texto":[{"t":"Gestionar el registro, la autenticación y la administración de la cuenta de EL CLIENTE."}]},{"tipo":"vinheta","texto":[{"t":"Procesar la contratación, publicación, renovación y visualización de los avisos clasificados, con o sin visibilidad destacada."}]},{"tipo":"vinheta","texto":[{"t":"Procesar pagos, emitir comprobantes electrónicos y cumplir con obligaciones tributarias y contables."}]},{"tipo":"vinheta","texto":[{"t":"Brindar atención al cliente, soporte técnico y atención de reclamos."}]},{"tipo":"vinheta","texto":[{"t":"Enviar comunicaciones operativas vinculadas al Servicio (confirmaciones, vencimientos, renovaciones)."}]},{"tipo":"vinheta","texto":[{"t":"Previa autorización expresa, remitir comunicaciones comerciales, promocionales y publicitarias sobre productos o servicios de LA EMPRESA o de terceros aliados."}]},{"tipo":"vinheta","texto":[{"t":"Realizar análisis estadísticos, segmentación y mejora continua de la plataforma y de la experiencia de usuario."}]},{"tipo":"vinheta","texto":[{"t":"Cumplir con obligaciones legales, requerimientos de autoridades competentes y prevención de fraude."}]},{"tipo":"titulo","texto":[{"t":"6. Consentimiento del titular"}]},{"tipo":"vinheta","texto":[{"t":"EL CLIENTE otorga su consentimiento previo, informado, expreso e inequívoco para el tratamiento de sus datos personales conforme a las finalidades descritas en la cláusula 5, al ejecutar el acceso, registro o contratación del Servicio mediante la aceptación electrónica de los presentes Términos y Condiciones."}]},{"tipo":"vinheta","texto":[{"t":"El consentimiento para finalidades distintas a la ejecución del contrato (por ejemplo, el envío de publicidad de terceros) podrá ser otorgado de manera separada y opcional, pudiendo EL CLIENTE marcar o desmarcar dicha opción en el formulario correspondiente, sin que ello afecte la prestación del Servicio principal."}]},{"tipo":"vinheta","texto":[{"t":"EL CLIENTE podrá revocar su consentimiento en cualquier momento, sin efectos retroactivos, conforme al procedimiento descrito en la cláusula 9 sobre derechos ARCO."}]},{"tipo":"titulo","texto":[{"t":"7. Banco de datos personales y encargo de tratamiento"}]},{"tipo":"vinheta","texto":[{"t":"Los datos personales de EL CLIENTE serán incorporados a un banco de datos de uso propio, titularidad de CORP LOZANOCHEFFER SAC, el cual será inscrito ante el Registro Nacional de Protección de Datos Personales administrado por la Autoridad Nacional de Protección de Datos Personales (ANPD), conforme a lo exigido por la Ley N° 29733 y su Reglamento."}]},{"tipo":"vinheta","texto":[{"t":"LA EMPRESA podrá encargar el tratamiento de determinados datos a proveedores de servicios tecnológicos, de hosting, de mensajería, de procesamiento de pagos o de analítica web, quienes actuarán como encargados de tratamiento, sujetos a obligaciones contractuales de confidencialidad y seguridad, y únicamente para los fines encomendados por LA EMPRESA."}]},{"tipo":"titulo","texto":[{"t":"8. Transferencia y flujo transfronterizo de datos"}]},{"tipo":"parrafo","texto":[{"t":"En caso de que LA EMPRESA contrate proveedores de servicios cuyos servidores o infraestructura se encuentren ubicados fuera del territorio peruano (incluyendo servicios de almacenamiento en la nube, pasarelas de pago internacionales o herramientas de analítica), dicho flujo transfronterizo de datos personales se realizará garantizando un nivel de protección adecuado, conforme a lo dispuesto en el artículo 15 de la Ley N° 29733 y los artículos 71 a 83 de su Reglamento, ya sea mediante la verificación de que el país de destino cuente con un nivel de protección adecuado, la suscripción de cláusulas contractuales de protección de datos, o la obtención del consentimiento de EL CLIENTE cuando ello sea exigible."}]},{"tipo":"titulo","texto":[{"t":"9. Derechos del titular de datos personales (Derechos ARCO)"}]},{"tipo":"parrafo","texto":[{"t":"EL CLIENTE, en su calidad de titular de datos personales, podrá ejercer en cualquier momento y de forma gratuita los siguientes derechos, reconocidos por la Ley N° 29733 y su Reglamento:"}]},{"tipo":"vinheta","texto":[{"t":"Acceso:","b":true},{"t":" conocer qué datos personales son objeto de tratamiento, su origen y las finalidades del mismo."}]},{"tipo":"vinheta","texto":[{"t":"Rectificación:","b":true},{"t":" solicitar la corrección de datos inexactos, incompletos o desactualizados."}]},{"tipo":"vinheta","texto":[{"t":"Cancelación o supresión:","b":true},{"t":" solicitar la eliminación de sus datos personales del banco de datos cuando ya no resulten necesarios para las finalidades para las cuales fueron recopilados, salvo que exista una obligación legal de conservarlos."}]},{"tipo":"vinheta","texto":[{"t":"Oposición:","b":true},{"t":" oponerse al tratamiento de sus datos personales para finalidades específicas, en particular respecto del envío de comunicaciones comerciales o publicitarias."}]},{"tipo":"vinheta","texto":[{"t":"Portabilidad:","b":true},{"t":" solicitar la entrega de sus datos personales en un formato estructurado, de uso común y lectura mecanizada, cuando ello sea técnicamente posible."}]},{"tipo":"parrafo","texto":[{"t":"Para ejercer estos derechos, EL CLIENTE deberá enviar una solicitud al correo electrónico avisos@coleffe.com, adjuntando copia de su documento de identidad y la descripción clara de su solicitud. LA EMPRESA atenderá dicha solicitud dentro del plazo establecido por la normativa vigente (veinte días hábiles, prorrogables conforme a ley). En caso de disconformidad con la respuesta, EL CLIENTE podrá presentar un reclamo ante la Autoridad Nacional de Protección de Datos Personales (ANPD)."}]},{"tipo":"titulo","texto":[{"t":"10. Plazo de conservación de los datos"}]},{"tipo":"parrafo","texto":[{"t":"Los datos personales de EL CLIENTE serán conservados durante el tiempo que dure la relación contractual derivada de la contratación del Servicio y, posteriormente, durante los plazos adicionales que resulten necesarios para el cumplimiento de obligaciones legales, tributarias, contables o de atención de reclamos, así como para la atención de los plazos de prescripción legalmente establecidos. Una vez cumplidas dichas finalidades, los datos serán eliminados, anonimizados o bloqueados, según corresponda."}]},{"tipo":"titulo","texto":[{"t":"11. Medidas de seguridad"}]},{"tipo":"parrafo","texto":[{"t":"LA EMPRESA implementa medidas de seguridad de índole técnica, organizativa y legal razonables y proporcionales al riesgo, destinadas a proteger los datos personales de EL CLIENTE contra su alteración, pérdida, tratamiento o acceso no autorizado, conforme a lo dispuesto en la Ley N° 29733, su Reglamento y la Directiva de Seguridad de la Información administrada por la ANPD. Dichas medidas incluyen, entre otras, el cifrado de información sensible, controles de acceso basados en roles, copias de seguridad periódicas y protocolos de respuesta ante incidentes de seguridad."}]},{"tipo":"titulo","texto":[{"t":"12. Cookies y tecnologías de seguimiento"}]},{"tipo":"parrafo","texto":[{"t":"La plataforma utiliza cookies y tecnologías similares con la finalidad de mejorar la experiencia de navegación, recordar preferencias, realizar análisis estadísticos y, de ser autorizado por EL CLIENTE, mostrar publicidad personalizada. EL CLIENTE puede configurar su navegador para rechazar o eliminar cookies, considerando que ello podría afectar el correcto funcionamiento de determinadas secciones de la plataforma."}]},{"tipo":"titulo","texto":[{"t":"13. Responsabilidad sobre el contenido de los avisos"}]},{"tipo":"parrafo","texto":[{"t":"EL CLIENTE es el único responsable del contenido, veracidad, legalidad y exactitud de la información incluida en los avisos clasificados publicados, así como de contar con la autorización correspondiente respecto de cualquier dato personal de terceros que decida incluir en dichos avisos. LA EMPRESA podrá, sin que ello genere obligación alguna, revisar, suspender o eliminar avisos que infrinjan la normativa vigente, derechos de terceros o las políticas de uso de la plataforma."}]},{"tipo":"titulo","texto":[{"t":"14. Vigencia, modificación y resolución"}]},{"tipo":"parrafo","texto":[{"t":"Estos Términos y Condiciones entrarán en vigencia desde el momento de su aceptación por parte de EL CLIENTE y se mantendrán vigentes durante todo el periodo de uso del Servicio. LA EMPRESA se reserva el derecho de modificar, suspender o discontinuar el Servicio, total o parcialmente, previa comunicación a través de los canales habituales de contacto, sin que ello genere derecho a indemnización a favor de EL CLIENTE, salvo lo dispuesto por norma imperativa."}]},{"tipo":"titulo","texto":[{"t":"15. Legislación aplicable y jurisdicción"}]},{"tipo":"parrafo","texto":[{"t":"Los presentes Términos y Condiciones se rigen por las leyes de la República del Perú. Cualquier controversia derivada de su interpretación, ejecución o cumplimiento será sometida a los jueces y tribunales del distrito judicial correspondiente al domicilio de LA EMPRESA, sin perjuicio de las normas de protección al consumidor que resulten aplicables y de las vías administrativas ante INDECOPI o la ANPD, según corresponda."}]},{"tipo":"titulo","texto":[{"t":"16. Canales de contacto"}]},{"tipo":"vinheta","texto":[{"t":"Razón social:","b":true},{"t":" CORP LOZANOCHEFFER SAC"}]},{"tipo":"vinheta","texto":[{"t":"RUC:","b":true},{"t":" 20616009061"}]},{"tipo":"vinheta","texto":[{"t":"Domicilio:","b":true},{"t":" Ramal Sun S/N – Huaca del Sol – Campiña de Moche"}]},{"tipo":"vinheta","texto":[{"t":"Correo de contacto / privacidad:","b":true},{"t":" avisos@coleffe.com"}]},{"tipo":"vinheta","texto":[{"t":"Teléfono:","b":true},{"t":" +51 957 531 755"}]},{"tipo":"nota","texto":[{"t":"Al hacer clic en \"Aceptar\", registrarse, contratar o publicar un aviso a través de la plataforma, EL CLIENTE declara haber leído y aceptado de manera libre, expresa e informada el presente documento de Términos y Condiciones y Política de Tratamiento de Datos Personales de CORP LOZANOCHEFFER SAC."}]}]'::jsonb,
   'Términos y Condiciones · Documento'),
  ('legal_actualizado', to_jsonb('16 de junio de 2026'::text),
   'Términos y Condiciones · Última actualización')
on conflict (key) do nothing;
